/* Task-authored mono PCM owner and offline ring, using the existing owned
 * sample registry/defaults. Source PCM never enters the CoreAudio device. */
#include "stage39_samples.c"
#define PCM_MAX 4096
#define RING 1024
typedef struct {uint32_t attached,file,data_offset,bytes,frames,head,queued,source,passes,limit;uint64_t consumed,mixed_hash,pcm_hash,nonzero,eos;int16_t pcm[PCM_MAX],queue[RING];} PCM;
typedef struct {uint32_t magic,version;uint64_t clock;PCM slots[CAP];} PCMImage;
typedef struct {State*base;PCMImage pcm;} Pool;
typedef struct {Image legacy;PCMImage pcm;} Full;
static uint64_t fnv(uint64_t h,const void*data,size_t n){const uint8_t*p=data;for(size_t j=0;j<n;j++){h^=p[j];h*=1099511628211ULL;}return h;}
static uint64_t clock46(Pool*p){uint32_t a[16];if(s37_stats(p->base->audio,a))return p->pcm.clock;return (uint64_t)a[8]|((uint64_t)a[9]<<32);}
static uint16_t rd16(const uint8_t*p){return p[0]|((uint16_t)p[1]<<8);}
static uint32_t rd32(const uint8_t*p){return p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}
static void fill46(PCM*c){while(c->queued<RING){if(c->limit&&c->passes>=c->limit)break;if(c->source==c->frames){c->passes++;if(c->limit&&c->passes>=c->limit)break;c->source=0;}c->queue[(c->head+c->queued)%RING]=c->pcm[c->source++];c->queued++;}}
static int pull46(Pool*p,uint32_t frames){for(int k=0;k<CAP;k++){PCM*c=&p->pcm.slots[k];uint32_t*w=p->base->image.slots[k].words;if(!c->attached||w[2]!=4)continue;if(w[22]!=22050||w[28]||w[29]||w[30])return UNSUPPORTED;
 for(uint32_t n=0;n<frames;n++){if(!c->queued){fill46(c);if(!c->queued){w[2]=2;c->eos++;break;}}int16_t raw=c->queue[c->head],pair[2];for(int ch=0;ch<2;ch++){pair[ch]=(int16_t)((int32_t)raw*(int32_t)w[25+ch]/2047);if(pair[ch])c->nonzero++;}c->mixed_hash=fnv(c->mixed_hash,pair,4);c->head=(c->head+1)%RING;c->queued--;c->consumed++;w[7]=(uint32_t)((c->consumed%c->frames)*2);if(c->consumed%c->frames==0&&w[17]>1)w[17]--;if(c->queued<RING/2)fill46(c);}
 if(w[2]==4&&!c->queued&&c->limit&&c->consumed>=(uint64_t)c->limit*c->frames){w[2]=2;c->eos++;w[7]=c->bytes;}}
 return OK;}
int s46_service(Pool*p){if(!p)return INVALID;uint64_t clock=clock46(p);if(clock<p->pcm.clock||clock-p->pcm.clock>22050*60)return UNSUPPORTED;uint32_t delta=(uint32_t)(clock-p->pcm.clock);p->pcm.clock=clock;return pull46(p,delta);}
void*s46_new(void*audio,uint32_t cap,uint32_t volume,const uint32_t*pan){Pool*p=calloc(1,sizeof(*p));if(!p)return NULL;p->base=s39_new(audio,cap,volume,pan);if(!p->base){free(p);return NULL;}p->pcm.magic=0x53343650;p->pcm.version=1;p->pcm.clock=clock46(p);return p;}
void s46_delete(Pool*p){if(p){s39_delete(p->base);memset(p,0,sizeof(*p));free(p);}}
int s46_allocate(Pool*p,uint32_t driver,uint32_t*out){return p?s39_allocate(p->base,driver,out):INVALID;}
int s46_init(Pool*p,uint32_t h){if(!p||s46_service(p)||!backend(p->base))return INVALID;int k=lookup(p->base,h);if(k<0)return INVALID;memset(&p->pcm.slots[k],0,sizeof(PCM));initialize(p->base,k);p->base->image.calls++;return OK;}
int s46_release(Pool*p,uint32_t h){if(!p||s46_service(p))return INVALID;int k=lookup(p->base,h);if(k<0)return INVALID;uint32_t*w=p->base->image.slots[k].words;if(w[28]||w[29]||w[30])return UNSUPPORTED;memset(&p->pcm.slots[k],0,sizeof(PCM));w[3]=w[4]=w[5]=w[6]=0;return s39_release(p->base,h);}
int s46_query(Pool*p,uint32_t h,uint32_t field,uint32_t*out){if(!p||s46_service(p))return INVALID;return s39_query(p->base,h,field,out);}
int s46_set(Pool*p,uint32_t h,uint32_t field,uint32_t value){if(!p||s46_service(p))return INVALID;int k=lookup(p->base,h);if(k<0)return INVALID;if(!p->pcm.slots[k].attached)return s39_set(p->base,h,field,value);uint32_t*w=p->base->image.slots[k].words;if(field!=17&&field!=22&&field!=23&&field!=24)return INVALID;if(field==22&&value!=22050)return UNSUPPORTED;if(field==17&&w[2]!=2)return UNSUPPORTED;w[field]=value;if(field==23||field==24)gains(p->base,w);if(field==17)p->pcm.slots[k].limit=value;p->base->image.calls++;return OK;}
int s46_bind(Pool*p,uint32_t h,uint32_t file,const void*raw,size_t n){if(!p||!raw||!file||n<44||n>65536||s46_service(p))return INVALID;int k=lookup(p->base,h);if(k<0)return INVALID;uint32_t*w=p->base->image.slots[k].words;if(w[2]!=2||w[28]||w[29]||w[30]||w[79]||w[105])return UNSUPPORTED;
 const uint8_t*b=raw;if(memcmp(b,"RIFF",4)||memcmp(b+8,"WAVE",4))return UNSUPPORTED;uint32_t end=rd32(b+4)+8;if(end>n||end<12)return UNSUPPORTED;uint32_t fmt=0,data=0,bytes=0;for(uint32_t pos=12;pos+8<=end;){uint32_t len=rd32(b+pos+4);if(len>end-pos-8)return UNSUPPORTED;if(!memcmp(b+pos,"fmt ",4)){if(len<16)return UNSUPPORTED;fmt=pos+8;}if(!memcmp(b+pos,"data",4)){data=pos+8;bytes=len;}uint32_t step=8+len+(len&1);if(step>end-pos)break;pos+=step;}
 if(!fmt||!data||!bytes||bytes%2||bytes/2>PCM_MAX||rd16(b+fmt)!=1||rd16(b+fmt+2)!=1||rd32(b+fmt+4)!=22050||rd32(b+fmt+8)!=44100||rd16(b+fmt+12)!=2||rd16(b+fmt+14)!=16)return UNSUPPORTED;
 PCM*c=&p->pcm.slots[k];memset(c,0,sizeof(*c));c->attached=1;c->file=file;c->data_offset=data;c->bytes=bytes;c->frames=bytes/2;c->limit=w[17];memcpy(c->pcm,b+data,bytes);c->pcm_hash=fnv(14695981039346656037ULL,c->pcm,bytes);c->mixed_hash=14695981039346656037ULL;w[3]=file+data;w[4]=0;w[5]=bytes;w[6]=0;w[7]=w[8]=0;w[20]=1;w[21]=1;w[22]=22050;w[11]=w[12]=w[13]=0;w[47]=256;w[48]=w[49]=0;gains(p->base,w);p->base->image.calls++;return OK;}
int s46_start_empty(Pool*p,uint32_t h){if(!p||s46_service(p)||!backend(p->base))return INVALID;int k=lookup(p->base,h);if(k<0)return INVALID;PCM*c=&p->pcm.slots[k];if(!c->attached)return s39_start_empty(p->base,h);uint32_t*w=p->base->image.slots[k].words;if(w[22]!=22050||w[28]||w[29]||w[30])return UNSUPPORTED;c->head=c->queued=c->source=c->passes=0;c->consumed=c->nonzero=c->eos=0;c->limit=w[17];c->mixed_hash=14695981039346656037ULL;w[7]=0;w[27]=1;w[2]=4;fill46(c);p->base->image.calls++;return OK;}
int s46_command(Pool*p,uint32_t h,uint32_t command){if(!p||s46_service(p))return INVALID;int k=lookup(p->base,h);if(k<0)return INVALID;uint32_t*w=p->base->image.slots[k].words;if(w[28]||w[29]||w[30])return UNSUPPORTED;if(command==1){if(w[2]==4)w[2]=8;}else if(command==2){if(w[2]==8||w[2]==2)w[2]=4;}else if(command==3){if(w[2]!=2){w[2]=2;w[16]=1;p->pcm.slots[k].eos++;}}else return INVALID;return OK;}
int s46_pull(Pool*p,uint32_t frames){return p?pull46(p,frames):INVALID;}
int s46_zero_reverb(Pool*p,uint32_t h){if(!p||s46_service(p))return INVALID;int k=lookup(p->base,h);if(k<0)return INVALID;p->base->image.slots[k].words[157]=p->base->image.slots[k].words[158]=p->base->image.slots[k].words[159]=0;return OK;}
int s46_drop_file(Pool*p,uint32_t file){if(!p||s46_service(p))return INVALID;for(int k=0;k<CAP;k++)if(p->pcm.slots[k].attached&&p->pcm.slots[k].file==file){uint32_t*w=p->base->image.slots[k].words;if(w[2]==4||w[2]==8)return UNSUPPORTED;memset(&p->pcm.slots[k],0,sizeof(PCM));w[3]=w[4]=w[5]=w[6]=0;}return OK;}
int s46_stats(Pool*p,uint32_t h,uint64_t*out){if(!p||!out||s46_service(p))return INVALID;int k=lookup(p->base,h);if(k<0)return INVALID;PCM*c=&p->pcm.slots[k];uint32_t*w=p->base->image.slots[k].words;uint64_t v[]={h,c->attached,w[2],c->file,c->data_offset,c->bytes,c->frames,w[22],w[17],w[23],w[24],w[25],w[26],c->queued,c->source,c->consumed,c->nonzero,c->eos,c->pcm_hash,c->mixed_hash,p->pcm.clock};memcpy(out,v,sizeof(v));return OK;}
size_t s46_size(void){return sizeof(Image);}
int s46_export(Pool*p,void*out,size_t n){if(!p||s46_service(p))return INVALID;return s39_export(p->base,out,n);}
static int valid_legacy(Pool*p,const Image*im){if(im->magic!=0x53333953||im->version!=1||im->capacity!=CAP||im->volume>127||im->master!=127||im->format!=3||memcmp(im->pan,p->base->image.pan,128*4))return INVALID;for(int k=0;k<CAP;k++){const Slot*b=&im->slots[k];if(!b->generation||b->generation>65535||b->words[0]!=0x5333394f||b->words[1]!=DRIVER||(b->words[2]!=1&&b->words[2]!=2&&b->words[2]!=4&&b->words[2]!=8)||b->words[28]||b->words[29]||b->words[30]||b->words[79]||b->words[105])return INVALID;}return OK;}
int s46_import(Pool*p,const void*in,size_t n){if(!p||!in||n!=sizeof(Image)||valid_legacy(p,in))return INVALID;memcpy(&p->base->image,in,n);p->pcm.clock=clock46(p);return OK;}
size_t s46_full_size(void){return sizeof(Full);}
int s46_full_export(Pool*p,void*out,size_t n){if(!p||!out||n!=sizeof(Full)||s46_service(p))return INVALID;Full*f=out;f->legacy=p->base->image;f->pcm=p->pcm;return OK;}
int s46_full_import(Pool*p,const void*in,size_t n){if(!p||!in||n!=sizeof(Full))return INVALID;const Full*f=in;if(valid_legacy(p,&f->legacy)||f->pcm.magic!=0x53343650||f->pcm.version!=1)return INVALID;for(int k=0;k<CAP;k++){const PCM*c=&f->pcm.slots[k];const uint32_t*w=f->legacy.slots[k].words;if(c->attached){if(!c->file||c->frames>PCM_MAX||!c->frames||c->bytes!=c->frames*2||c->head>=RING||c->queued>RING||c->source>c->frames||w[3]!=c->file+c->data_offset||w[5]!=c->bytes||w[22]!=22050||c->pcm_hash!=fnv(14695981039346656037ULL,c->pcm,c->bytes))return INVALID;}else if(w[3]||w[5])return INVALID;}p->base->image=f->legacy;p->pcm=f->pcm;return OK;}
